mapper.select:
SELECT 
FROM gt_investment_plan
WHERE org_id = #{orgId}

    AND plan_no LIKE CONCAT('%', #{planNo}, '%')


    AND plan_name LIKE CONCAT('%', #{planName}, '%')


    AND plan_status = #{planStatus}


    AND investment_type = #{investmentType}


    AND plan_start_date >= #{startDate}


    AND plan_end_date <= #{endDate}

ORDER BY create_time DESC

SELECT 
FROM gt_investment_plan
WHERE plan_no = #{planNo} AND org_id = #{orgId}

SELECT COALESCE(SUM(plan_amount), 0)
FROM gt_investment_plan
WHERE org_id = #{orgId}

SELECT COALESCE(SUM(invested_amount), 0)
FROM gt_investment_plan
WHERE org_id = #{orgId}

SELECT COALESCE(SUM(remaining_amount), 0)
FROM gt_investment_plan
WHERE org_id = #{orgId}

SELECT COUNT(*)
FROM gt_investment_plan
WHERE plan_no = #{planNo} AND org_id = #{orgId}

    AND plan_id != #{excludeId}

SELECT plan_id, plan_no, plan_name, 'OVERDUE' as alertType, '计划已逾期' as alertMessage, plan_end_date as alertDate FROM gt_investment_plan WHERE plan_status IN ('APPROVED', 'EXECUTING') AND plan_end_date < CURDATE() AND org_id = #{orgId}
UNION ALL
SELECT plan_id, plan_no, plan_name, 'LOW_PERFORMANCE' as alertType, '实际收益率低于预期' as alertMessage, update_time as alertDate FROM gt_investment_plan WHERE actual_return_rate < expected_return_rate * 0.8 AND org_id = #{orgId}
